/**
 * Audit event record representing an immutable regulatory and operational audit entry
 */
export type AuditEventResponse = {
    /**
     * Unique audit event identifier
     */
    eventId?: string;
    /**
     * Category of event: FINANCIAL, ACCOUNT_LIFECYCLE, SECURITY, OPERATIONAL
     */
    category?: string;
    /**
     * Specific event type
     */
    eventType?: string;
    /**
     * Timestamp when the event occurred
     */
    eventTime?: string;
    /**
     * Identifier of actor who initiated the event
     */
    actorId?: string;
    /**
     * Type of actor: HUMAN, SERVICE, SYSTEM
     */
    actorType?: string;
    /**
     * Principal identifier
     */
    principalId?: string;
    /**
     * Client or customer ID if applicable
     */
    clientId?: string;
    /**
     * Source channel: API, BACKOFFICE, BATCH, SYSTEM_SCHEDULED
     */
    sourceChannel?: string;
    /**
     * Associated account IDs
     */
    accountIds?: Array<(string)>;
    /**
     * Associated transaction ID if applicable
     */
    transactionId?: string;
    /**
     * HTTP or workflow request ID
     */
    requestId?: string;
    /**
     * Distributed correlation ID
     */
    correlationId?: string;
    /**
     * Distributed trace ID
     */
    traceId?: string;
    /**
     * Business or operational reason for the action
     */
    reason?: string;
    /**
     * Authorization context / permissions evaluated
     */
    authorizationContext?: string;
    /**
     * Previous state before the event
     */
    previousState?: string;
    /**
     * Resulting state after the event
     */
    resultingState?: string;
    /**
     * Business date of the event
     */
    businessDate?: string;
    /**
     * Execution outcome: SUCCESS, FAILED, DENIED
     */
    status?: string;
    /**
     * Additional context or payload details
     */
    details?: string;
    type?: string;
    timestamp?: string;
};

